# ============================================================================
# IMAGENS OFICIAIS DA REGULARIZE EMBUTIDAS (EXTRAÍDAS DA PLANILHA ORIGINAL)
# Formato RGB sobre fundo branco (sem canal alpha) para nunca borrar ou escurecer
# em impressoras P&B ou visualizadores de PDF!
# ============================================================================
MARCA_DAGUA_REGULARIZE_B64 = ""
LOGO_REGULARIZE_PB_B64 = ""

# Dimensões úteis da página A4 com margens estreitas (0,65 cm de cada lado)
MARGEM = 0.65 * cm
LARGURA_UTIL = A4[0] - (2 * MARGEM)   # ~19,70 cm
ALTURA_UTIL = A4[1] - (2 * MARGEM)    # ~28,40 cm


# ============================================================================
# FUNÇÕES DE FORMATAÇÃO (PADRÃO BRASILEIRO PT-BR)
# ============================================================================
def fmt_moeda(valor):
    """Formata 500000 como 'R$ 500.000,00'."""
    try:
        v = float(valor or 0)
    except (TypeError, ValueError):
        v = 0.0
    sinal = "-" if v < 0 else ""
    texto = f"{abs(v):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"{sinal}R$ {texto}"


def fmt_doc(cpf_cnpj):
    """Formata CPF (000.000.000-00) ou CNPJ (00.000.000/0000-00)."""
    d = "".join(ch for ch in str(cpf_cnpj or "") if ch.isdigit())
    if len(d) == 11:
        return f"{d[:3]}.{d[3:6]}.{d[6:9]}-{d[9:]}"
    if len(d) == 14:
        return f"{d[:2]}.{d[2:5]}.{d[5:8]}/{d[8:12]}-{d[12:]}"
    return str(cpf_cnpj or "")


def fmt_cep(cep):
    """Formata CEP como 00000-000."""
    d = "".join(ch for ch in str(cep or "") if ch.isdigit())
    if len(d) == 8:
        return f"{d[:5]}-{d[5:]}"
    return str(cep or "")


def fmt_data_extenso(dt=None):
    """Retorna data por extenso em português: '25 de novembro de 2026'."""
    if not dt:
        dt = date.today()
    elif isinstance(dt, str):
        try:
            dt = datetime.strptime(dt[:10], "%Y-%m-%d").date()
        except ValueError:
            return dt
    meses = [
        "janeiro", "fevereiro", "março", "abril", "maio", "junho",
        "julho", "agosto", "setembro", "outubro", "novembro", "dezembro",
    ]
    return f"{dt.day:02d} de {meses[dt.month - 1]} de {dt.year}"


def fmt_data_br(dt=None):
    """Retorna data como '25/11/2026'."""
    if not dt:
        dt = date.today()
    elif isinstance(dt, str):
        try:
            dt = datetime.strptime(dt[:10], "%Y-%m-%d").date()
        except ValueError:
            return dt
    return dt.strftime("%d/%m/%Y")


def safe(texto):
    """Protege caracteres especiais para o motor PDF."""
    return escape(str(texto or ""))


# ============================================================================
# MARCA D'ÁGUA OFICIAL DA REGULARIZE (EM TODAS AS FOLHAS IMPRESSAS)
# ============================================================================
def desenhar_marca_dagua(canvas, doc):
    """
    Desenha a marca d'água oficial da Regularize Assessoria Rural centralizada
    no fundo de CADA folha A4, em escala de cinza suave própria para P&B.
    """
    canvas.saveState()
    largura_pag, altura_pag = A4
    wm_bytes = base64.b64decode(MARCA_DAGUA_REGULARIZE_B64)
    img_reader = ImageReader(io.BytesIO(wm_bytes))

    # Tamanho proporcional generoso centralizado na folha (mesmo padrão do Excel)
    wm_w = 16.2 * cm
    wm_h = 12.9 * cm
    x = (largura_pag - wm_w) / 2.0
    y = (altura_pag - wm_h) / 2.0
    canvas.drawImage(
        img_reader, x, y, width=wm_w, height=wm_h,
        preserveAspectRatio=True, anchor="c",
    )
    canvas.restoreState()


