def _logo_cabecalho():
    """Retorna o logo oficial da Regularize em P&B para o cabeçalho."""
    logo_bytes = base64.b64decode(LOGO_REGULARIZE_PB_B64)
    return RLImage(io.BytesIO(logo_bytes), width=4.3 * cm, height=1.26 * cm)


def bloco_cabecalho_planilha(titulo, est, subtitulo_extra=""):
    """Cabeçalho padrão em P&B ocupando toda a largura útil (19,7 cm)."""
    txt_dir = f"<b>{safe(titulo)}</b>"
    if subtitulo_extra:
        txt_dir += f"<br/><font size=9.5>{safe(subtitulo_extra)}</font>"

    t = Table(
        [[_logo_cabecalho(), Paragraph(txt_dir, est["titulo"])]],
        colWidths=[4.9 * cm, LARGURA_UTIL - 4.9 * cm],
    )
    t.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("ALIGN", (0, 0), (0, 0), "CENTER"),
        ("BOX", (0, 0), (-1, -1), 0.9, est["cor_borda"]),
        ("LINEBEFORE", (1, 0), (1, 0), 0.6, est["cor_borda"]),
        ("LEFTPADDING", (0, 0), (-1, -1), 6),
        ("RIGHTPADDING", (0, 0), (-1, -1), 6),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
    ]))
    return [t, Spacer(1, 5)]


def faixa_secao(titulo, est):
    """Faixa cinza-claro P&B para títulos de seção em toda a largura da folha."""
    t = Table([[Paragraph(safe(titulo), est["secao"])]], colWidths=[LARGURA_UTIL])
    t.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), est["cor_faixa"]),
        ("BOX", (0, 0), (-1, -1), 0.7, est["cor_borda"]),
        ("TOPPADDING", (0, 0), (-1, -1), 3.2),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 3.2),
    ]))
    return t


def tabela_pb(dados, col_widths, est, cabecalho_cinza=False, pad_v=4.0, pad_h=5):
    """Tabela P&B limpa com células transparentes para deixar a marca d'água visível."""
    t = Table(dados, colWidths=col_widths)
    regras = [
        ("GRID", (0, 0), (-1, -1), 0.55, est["cor_borda"]),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), pad_h),
        ("RIGHTPADDING", (0, 0), (-1, -1), pad_h),
        ("TOPPADDING", (0, 0), (-1, -1), pad_v),
        ("BOTTOMPADDING", (0, 0), (-1, -1), pad_v),
        ("FONTSIZE", (0, 0), (-1, -1), 9.2),
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.black),
    ]
    if cabecalho_cinza:
        regras.extend([
            ("BACKGROUND", (0, 0), (-1, 0), est["cor_faixa"]),
            ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ])
    t.setStyle(TableStyle(regras))
    return t


def bloco_assinatura_padrao(est, local, data_dt, nome, cpf, rotulo="Assinatura do Proponente / Cliente", espaco_antes=18):
    """Bloco de Local/Data + Linha de Assinatura + Nome e CPF formatado."""
    return [
        Spacer(1, espaco_antes),
        Paragraph(f"{safe(local)}, {fmt_data_extenso(data_dt)}.", est["centro_grande"]),
        Spacer(1, 34),
        Paragraph("____________________________________________________________________", est["centro_grande"]),
        Paragraph(f"<b>{safe(nome) or ' '}</b>", est["centro_grande"]),
        Paragraph(f"CPF/CNPJ: {fmt_doc(cpf) if cpf else '______________________________'}", est["centro"]),
        Paragraph(safe(rotulo), ParagraphStyle("RotAssPB", parent=est["centro"], fontSize=8.5)),
    ]


def distribuir_na_folha(topo_blocos, rodape_blocos, altura_disponivel=ALTURA_UTIL - 0.15 * cm):
    """
    Distribui o documento dentro da folha A4 inteira com margens estreitas:
    mede exatamente quanto o topo + rodapé ocupam e insere um espaçador
    calculado entre eles para posicionar as assinaturas na parte inferior da folha,
    sem nunca deixar o documento amontoado lá em cima nem quebrar para a 2ª folha!
    """
    h_topo = sum(f.wrap(LARGURA_UTIL, altura_disponivel)[1] for f in topo_blocos)
    h_rodape = sum(f.wrap(LARGURA_UTIL, altura_disponivel)[1] for f in rodape_blocos)
    sobra = altura_disponivel - h_topo - h_rodape
    elementos = list(topo_blocos)
    if sobra > 0.4 * cm:
        # Deixa uma pequena folga natural no pé (~0,6 cm) e empurra o rodapé para baixo
        espaco_meio = max(0.3 * cm, sobra - 0.6 * cm)
        elementos.append(Spacer(1, espaco_meio))
    elementos.extend(rodape_blocos)
    return elementos


def enquadrar_uma_folha(elementos):
    """
    Garante que CADA documento ocupe EXATAMENTE 1 folha A4 (nunca estoura para 2ª folha),
    mantendo 100% do tamanho original quando cabe na folha e ajustando suavemente só se
    algum texto digitado pelo usuário for excepcionalmente longo.
    """
    return KeepInFrame(
        LARGURA_UTIL,
        ALTURA_UTIL,
        elementos,
        mode="shrink",
        hAlign="CENTER",
        vAlign="TOP",
    )


# ============================================================================
# 1. NOVA PROPOSTA (PADRÃO FIEL DA PLANILHA — FOLHA A4 CHEIA P&B)
# ============================================================================
def doc_nova_proposta(d, est):
    W = LARGURA_UTIL
    topo = bloco_cabecalho_planilha("CARTA-PROPOSTA", est)

    topo.append(tabela_pb([
        [
            Paragraph(f"<b>Local:</b> {safe(d.get('local_emissao'))}", est["normal"]),
            Paragraph(f"<b>Data:</b> {fmt_data_br(d.get('data_proposta'))}", est["normal"]),
            Paragraph(f"<b>Parceiro:</b> {safe(d.get('parceiro') or EMPRESA['nome_fantasia'])}", est["normal"]),
            Paragraph(f"<b>Banco:</b> {safe(d.get('banco_destino'))}", est["normal"]),
        ]
    ], [3.6 * cm, 3.2 * cm, 7.6 * cm, 5.3 * cm], est, pad_v=2.6))
    topo.append(Spacer(1, 3.5))

    # DADOS DO CLIENTE
    topo.append(faixa_secao("DADOS DO CLIENTE", est))
    topo.append(tabela_pb([
        [
            Paragraph(f"<b>Nome:</b> {safe(d.get('cliente_nome'))}", est["normal"]),
            Paragraph(f"<b>Enquadramento:</b> {safe(d.get('tipo_cliente'))}", est["normal"]),
        ],
        [
            Paragraph(f"<b>CPF/CNPJ:</b> {fmt_doc(d.get('cliente_cpf'))}", est["normal"]),
            Paragraph(f"<b>Telefone:</b> {safe(d.get('cliente_telefone'))}", est["normal"]),
        ],
    ], [12.2 * cm, 7.5 * cm], est, pad_v=2.6))
    topo.append(Spacer(1, 3.5))

    # DADOS DA PROPRIEDADE BENEFICIADA E OPERAÇÃO
    topo.append(faixa_secao("DADOS DA PROPRIEDADE BENEFICIADA", est))
    topo.append(tabela_pb([
        [
            Paragraph(f"<b>Imóvel Beneficiado:</b> {safe(d.get('imovel_beneficiado_texto'))}", est["normal"]),
            Paragraph(f"<b>CEP:</b> {fmt_cep(d.get('cep'))}", est["normal"]),
        ],
        [
            Paragraph(f"<b>Rua:</b> {safe(d.get('rua'))}", est["normal"]),
            Paragraph(f"<b>Localidade:</b> {safe(d.get('localidade'))}", est["normal"]),
        ],
        [
            Paragraph(f"<b>Cidade:</b> {safe(d.get('cidade'))} &nbsp;|&nbsp; <b>UF:</b> {safe(d.get('uf'))}", est["normal"]),
            Paragraph(f"<b>Bairro:</b> {safe(d.get('bairro'))}", est["normal"]),
        ],
        [
            Paragraph(f"<b>Tipo de Serviço (Linha):</b> {safe(d.get('tipo_servico'))}", est["normal"]),
            Paragraph(f"<b>Item:</b> {safe(d.get('item_financiado'))}", est["normal"]),
        ],
        [
            Paragraph(f"<b>Cultura:</b> {safe(d.get('cultura'))} &nbsp;|&nbsp; <b>Carência:</b> {safe(d.get('carencia'))}", est["normal"]),
            Paragraph(f"<b>Valor Proposto:</b> <b>{fmt_moeda(d.get('valor_proposto'))}</b>", est["normal"]),
        ],
    ], [11.5 * cm, 8.2 * cm], est, pad_v=2.6))
    topo.append(Spacer(1, 3.5))

    # DOCUMENTOS (3 COLUNAS: PROPONENTE | IMÓVEL/CONTABILIDADE | COOBRIGADOS)
    topo.append(faixa_secao("DOCUMENTOS", est))
    chk = d.get("checklist_docs") or {}
    linhas_chk = [[
        Paragraph("<b>PROPONENTE</b>", est["compacto"]),
        Paragraph("<b>IMÓVEL / CONTABILIDADE</b>", est["compacto"]),
        Paragraph("<b>COOBRIGADOS</b>", est["compacto"]),
    ]]
    col_meio = [
        f"[{'X' if chk.get('imov_' + item) else ' '}] {safe(item)}" for item in DOCS_IMOVEL
    ] + [
        "",
        f"<b>Contabilidade:</b> {safe(d.get('contabilidade_nome'))}",
        f"<b>CNPJ Contab.:</b> {fmt_doc(d.get('contabilidade_cnpj'))}",
        f"<b>Tipo de Envio:</b> {safe(d.get('tipo_envio_docs'))}",
        f"<b>Envio de Docs:</b> {safe(d.get('data_envio_docs')) or '___/___/______'}",
        f"<b>Vínculo Imóvel:</b> {safe(d.get('tipo_cliente'))}",
    ]
    max_len = max(len(DOCS_PROPONENTE), len(col_meio), len(DOCS_COOBRIGADOS))
    for i in range(max_len):
        c1 = f"[{'X' if chk.get('prop_' + DOCS_PROPONENTE[i]) else ' '}] {safe(DOCS_PROPONENTE[i])}" if i < len(DOCS_PROPONENTE) else ""
        c2 = col_meio[i] if i < len(col_meio) else ""
        c3 = f"[{'X' if chk.get('coob_' + DOCS_COOBRIGADOS[i]) else ' '}] {safe(DOCS_COOBRIGADOS[i])}" if i < len(DOCS_COOBRIGADOS) else ""
        linhas_chk.append([
            Paragraph(c1, est["compacto"]),
            Paragraph(c2, est["compacto"]),
            Paragraph(c3, est["compacto"]),
        ])
    topo.append(tabela_pb(linhas_chk, [7.3 * cm, 6.7 * cm, 5.7 * cm], est, cabecalho_cinza=True, pad_v=2.2))
    topo.append(Spacer(1, 5))

    # MARGEM CRÉDITO PESSOAL (SEPARADA DE AVALISTAS)
    topo.append(faixa_secao("MARGEM CRÉDITO PESSOAL", est))
    topo.append(tabela_pb([
        [
            Paragraph(f"<b>Crédito:</b> {safe(d.get('credito_tipo')) or '—'}", est["normal"]),
            Paragraph(f"<b>Valor:</b> {fmt_moeda(d.get('credito_valor'))}", est["normal"]),
            Paragraph(f"<b>Benefício:</b> {fmt_moeda(d.get('beneficio_valor'))}", est["normal"]),
        ],
        [
            Paragraph(f"<b>Parcela Consórcio:</b> {fmt_moeda(d.get('parcela_consorcio'))}", est["normal"]),
            Paragraph(f"<b>Nº Parcelas:</b> {int(d.get('num_parcelas_consorcio') or 0) or '—'}", est["normal"]),
            Paragraph("", est["normal"]),
        ],
    ], [6.9 * cm, 6.4 * cm, 6.4 * cm], est, pad_v=3.5))
    topo.append(Spacer(1, 5))

    # PARECER DA AGÊNCIA BANCÁRIA + ASSINATURAS NO RODAPÉ DA FOLHA
    rodape = [faixa_secao("PARECER DA AGÊNCIA BANCÁRIA", est)]
    parecer_txt = safe(d.get("parecer_agencia", "")).replace("\n", "<br/>")
    conteudo_parecer = Paragraph(parecer_txt if parecer_txt.strip() else "<br/><br/><br/>", est["normal"])
    t_par = Table(
        [
            [conteudo_parecer],
            [Paragraph("Ass. Agência: ______________________________________________", est["direita"])],
        ],
        colWidths=[W],
    )
    t_par.setStyle(TableStyle([
        ("BOX", (0, 0), (-1, -1), 0.7, est["cor_borda"]),
        ("LEFTPADDING", (0, 0), (-1, -1), 6),
        ("RIGHTPADDING", (0, 0), (-1, -1), 6),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
    ]))
    rodape.append(t_par)
    rodape.append(Spacer(1, 5))

    # ASSINATURAS (GRADE 2x2):
    #   Esquerda: Cliente + CPF / embaixo: Análise do Banco (Nome Legível)
    #   Direita (na frente): Avalista + CPF / embaixo: Cônjuge do Avalista + CPF
    rodape.append(faixa_secao("ASSINATURAS", est))

    def _cel_ass(rotulo, nome="", cpf="", sem_cpf=False):
        linhas = [
            "<br/>",
            "________________________________________________",
            f"<b>{safe(rotulo)}</b>",
        ]
        if not sem_cpf:
            linhas.append(f"Nome: {safe(nome) or '________________________________________'}")
            linhas.append(f"CPF/CNPJ: {fmt_doc(cpf) if cpf else '__________________________________'}")
        else:
            linhas.append("Nome Legível: __________________________________")
            linhas.append("Matrícula / Carimbo: ____________________________")
        return Paragraph("<br/>".join(linhas), est["centro"])

    t_ass = Table(
        [
            [
                _cel_ass("Assinatura do Cliente (Proponente)", d.get("cliente_nome"), d.get("cliente_cpf")),
                _cel_ass("Avalista", d.get("avalista_nome"), d.get("avalista_cpf")),
            ],
            [
                _cel_ass("Análise do Banco (Nome Legível)", sem_cpf=True),
                _cel_ass("Cônjuge do Avalista", d.get("conjuge_avalista_nome"), d.get("conjuge_avalista_cpf")),
            ],
        ],
        colWidths=[W / 2.0, W / 2.0],
    )
    t_ass.setStyle(TableStyle([
        ("GRID", (0, 0), (-1, -1), 0.55, est["cor_borda"]),
        ("VALIGN", (0, 0), (-1, -1), "BOTTOM"),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
    ]))
    rodape.append(t_ass)

    return [enquadrar_uma_folha(distribuir_na_folha(topo, rodape))]


